package com.brainserve.onboarding.notifications.domain.model;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notifications",schema="client_onboarding") public class Notification {
@Id private UUID id;@Column(name="organization_id",nullable=false)private UUID organizationId;@Column(name="recipient_user_id",nullable=false)private UUID recipientUserId;@Column(name="recipient_type",nullable=false,length=16)private String recipientType;@Column(name="template_id")private UUID templateId;@Column(name="event_type",nullable=false,length=100)private String eventType;@Column(name="source_type",nullable=false,length=80)private String sourceType;@Column(name="source_id",nullable=false)private UUID sourceId;@Column(name="project_id")private UUID projectId;@Column(nullable=false,length=300)private String title;@Column(nullable=false,length=6000)private String body;@Column(name="action_url",length=1000)private String actionUrl;@Column(name="dedupe_key",nullable=false,length=220)private String dedupeKey;@Column(name="read_at")private Instant readAt;@Column(name="created_at",nullable=false)private Instant createdAt;protected Notification(){}
public Notification(UUID id,UUID org,UUID userId,String recipientType,UUID templateId,String eventType,String sourceType,UUID sourceId,UUID projectId,String title,String body,String actionUrl,String dedupeKey,Instant now){this.id=id;this.organizationId=org;this.recipientUserId=userId;this.recipientType=recipientType;this.templateId=templateId;this.eventType=eventType;this.sourceType=sourceType;this.sourceId=sourceId;this.projectId=projectId;this.title=title;this.body=body;this.actionUrl=actionUrl;this.dedupeKey=dedupeKey;this.createdAt=now;}
public void markRead(Instant now){if(readAt==null)readAt=now;} public UUID getId(){return id;}public UUID getOrganizationId(){return organizationId;}public UUID getRecipientUserId(){return recipientUserId;}public String getRecipientType(){return recipientType;}public UUID getTemplateId(){return templateId;}public String getEventType(){return eventType;}public String getSourceType(){return sourceType;}public UUID getSourceId(){return sourceId;}public UUID getProjectId(){return projectId;}public String getTitle(){return title;}public String getBody(){return body;}public String getActionUrl(){return actionUrl;}public Instant getReadAt(){return readAt;}public Instant getCreatedAt(){return createdAt;}public String getDedupeKey(){return dedupeKey;}
}
